package com.et.cloud.controller;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Base64;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

/** Authenticates metadata generated by Cloud's file operations, never model text. */
final class AgentPersonalFileEvidence {
    private static final ObjectMapper JSON = new ObjectMapper();
    static String issue(String secret, long user, String path, String version, long start, long end) {
        try {
            var data = JSON.createObjectNode();
            data.put("user", Long.toString(user)); data.put("path", path); data.put("version", version);
            data.put("start", start); data.put("end", end);
            byte[] bytes = JSON.writeValueAsBytes(data);
            return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes) + "." +
                    Base64.getUrlEncoder().withoutPadding().encodeToString(mac(secret, bytes));
        } catch (Exception e) { throw new IllegalStateException("Cannot create file evidence", e); }
    }
    static JsonNode verify(String secret, String token, long user) {
        try {
            if (secret == null || secret.isEmpty() || token == null || token.length() > 8192) throw new IllegalArgumentException();
            String[] parts = token.split("\\.", -1);
            if (parts.length != 2) throw new IllegalArgumentException();
            byte[] bytes = Base64.getUrlDecoder().decode(parts[0]);
            if (!MessageDigest.isEqual(mac(secret, bytes), Base64.getUrlDecoder().decode(parts[1]))) throw new IllegalArgumentException();
            JsonNode data = JSON.readTree(bytes);
            if (!Long.toString(user).equals(data.path("user").asText()) || !data.path("path").isTextual()
                    || !data.path("version").isTextual() || !data.path("start").isIntegralNumber()
                    || !data.path("end").isIntegralNumber() || !data.path("start").canConvertToLong()
                    || !data.path("end").canConvertToLong() || data.path("start").longValue() < 0
                    || data.path("end").longValue() < data.path("start").longValue()) throw new IllegalArgumentException();
            return data;
        } catch (Exception e) { throw new IllegalArgumentException("Invalid personal file reference"); }
    }
    private static byte[] mac(String secret, byte[] bytes) throws Exception {
        if (secret == null || secret.isEmpty()) throw new IllegalArgumentException();
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
        mac.update("agent-file-evidence-v1\0".getBytes(StandardCharsets.UTF_8));
        return mac.doFinal(bytes);
    }
}
